import { Button } from 'react-bootstrap';
import styled from 'styled-components';

export const FileAlreadyAdded = styled.div`
  align-items: left;
  display: flex;
  flex-direction: row;
  font-family: 'Quicksand Medium';
  line-height: 24px;
  padding-bottom: 8px;
  svg{
    cursor: pointer;
  }
  span{
    overflow: hidden;
    white-space:nowrap;
    text-overflow:ellipsis;
  }
`;

export const QuestionContainer = styled.div`
	align-items: center;
	display: flex;
	flex-direction: row;
	margin-bottom: 10px;
	justify-content: flex-start;
	width: 100%;
`;

export const QuestionFlag = styled(({ flagged, ...props }) => <div {...props} />)`
  background-image: url(${({ flagged }) => flagged ? 'data:image/svg+xml;base64,' : 'data:image/svg+xml;base64,'});
  cursor: pointer;
  height: 20px;
  margin-left: 28px;
  transition: background-image 0.2s ease-in-out;
  width: 20px;
  @media (max-width: 575px){
    margin-left: 4px;
  }
`;

export const CommentApproveButton = styled(Button)`
  font-size: 10px !important;
  padding: 5px 10px;
`

export const TaxDocumentName = styled.div`
	display: flex;
  margin-bottom: 5px;
`;

export const TaxDocumentLabelContainer = styled.div`
  display: flex;
  flex: 1;
	flex-direction: column;
`
